{"kind":"tool","id":"i1ri9okIkWc","toolName":"write_file","input":{"path":"probe.tmp.mjs","instructions":"Temporary connectivity probe (deleted after use)","content":"import fs from 'node:fs';

const env = Object.fromEntries(
  fs.readFileSync('.env', 'utf8')
    .split(/\r?\n/)
    .filter((l) => l.includes('=') && !l.trim().startsWith('#'))
    .map((l) => {
      const i = l.indexOf('=');
      return [l.slice(0, i).trim(), l.slice(i + 1).trim().replace(/^["']|["']$/g, '')];
    }),
);

const url = env.VITE_SUPABASE_URL;
const anon = env.VITE_SUPABASE_ANON_KEY;
const svc = env.SUPABASE_SERVICE_ROLE_KEY;

async function read(res) {
  const t = await res.text();
  try { return JSON.parse(t); } catch { return t.slice(0, 200); }
}

for (const table of ['weddings', 'guests', 'guest_sessions', 'media', 'messages', 'inquiries']) {
  const res = await fetch(`${url}/rest/v1/${table}?select=*&limit=1`, {
    headers: { apikey: anon, Authorization: `Bearer ${anon}` },
  });
  const body = await read(res);
  console.log(
    `${table}: HTTP ${res.status}`,
    res.status >= 400 ? JSON.stringify(body).slice(0, 180) : `ok, rows=${Array.isArray(body) ? body.length : '?'}`,
  );
}

console.log('--- auth admin ---');
console.log('service role key is a JWT:', Boolean(svc && svc.split('.').length === 3));
if (svc) {
  const res = await fetch(`${url}/auth/v1/admin/users?per_page=50`, {
    headers: { apikey: svc, Authorization: `Bearer ${svc}` },
  });
  const body = await read(res);
  console.log('GET /auth/v1/admin/users ->', res.status);
  if (body?.users) {
    console.log('accounts:', body.users.map((u) => `${u.email} confirmed=${Boolean(u.email_confirmed_at)}`).join(' | ') || '(none)');
  } else {
    console.log(JSON.stringify(body).slice(0, 300));
  }
}
