const token = session?.access_token;
if (!token) process.exit(1);

const authHeaders = { apikey: anon, Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' };

// 4. read as authenticated owner
const list = await fetch(`${url}/rest/v1/weddings?select=*&order=wedding_date.desc`, { headers: authHeaders });
const listBody = await read(list);
console.log('authenticated GET weddings ->', list.status, list.status >= 400 ? JSON.stringify(listBody).slice(0, 220) : `rows=${listBody.length}`);

// 5. create a wedding like the dashboard form does
const slug = 'test-qr-demo';
const payload = {
  slug,
  couple_name_1: 'Test',
