  wedding_date: new Date().toISOString().slice(0, 10),
  message: 'Created by an automated QR-flow check.',
  max_photos_per_guest: 10,
  max_videos_per_guest: 5,
};
const ins = await fetch(`${url}/rest/v1/weddings`, {
  method: 'POST',
  headers: { ...authHeaders, Prefer: 'return=representation' },
  body: JSON.stringify(payload),
});
const insBody = await read(ins);
