  headers: { apikey: anon, Authorization: `Bearer ${anon}` },
});
const pubBody = await read(pub);
console.log('anon GET wedding by slug ->', pub.status, JSON.stringify(pubBody).slice(0, 220));

fs.writeFileSync('probe.tmp.json', JSON.stringify({ email: EMAIL, password: PASSWORD, slug, token }, null, 2));
