export function getVideoDuration(file) {
  return new Promise((resolve) => {
    const url = URL.createObjectURL(file);
    const video = document.createElement('video');
    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      video.removeAttribute('src');
      video.load();
      URL.revokeObjectURL(url);
      resolve(Number.isFinite(value) && value > 0 ? value : null);
    };
    video.preload = 'metadata';
    video.onloadedmetadata = () => {
      if (Number.isFinite(video.duration) && video.duration > 0) return finish(video.duration);
      // Some recordings (fragmented MP4 / MediaRecorder WebM) report Infinity
      // until the browser scans to the end.
      video.ondurationchange = () => {
        if (Number.isFinite(video.duration) && video.duration > 0) finish(video.duration);
      };
      video.currentTime = 1e101;
    };
    video.onerror = () => finish(null);
    video.src = url;
  });
}
```
