useEffect(() => {
  if (!open) return undefined;
  let cancelled = false;
  setReady(false); setError(null);
  const start = async () => {
    if (!navigator.mediaDevices?.getUserMedia) { setError('...'); return; }
    try {
      let stream;
      try { stream = await navigator.mediaDevices.getUserMedia({ video: {facingMode: facing, width:{ideal:1920}, height:{ideal:1080}}, audio: true }); }
      catch { stream = await navigator.mediaDevices.getUserMedia({ video: {facingMode: facing, width:{ideal:1920}, height:{ideal:1080}}, audio: false }); }
      if (cancelled) { stream.getTracks().forEach(t=>t.stop()); return; }
      streamRef.current = stream;
      if (videoRef.current) { videoRef.current.srcObject = stream; await videoRef.current.play().catch(()=>{}); }
      setReady(true);
    } catch (err) {
      setError(err?.name === 'NotAllowedError' ? 'Camera access was blocked...' : ...);
    }
  };
  start();
  return () => { cancelled = true; stopStream(); };
}, [open, facing]);
