  if (!streamRef.current || recording) return;
  const videoSlots = remainingVideos - countVideos;
  if (videoSlots <= 0) { setError(...); return; }
  const mimeType = pickMimeType();
  if (typeof MediaRecorder === 'undefined' || !mimeType) { setError('Video recording is not supported by this browser.'); return; }
  chunksRef.current = [];
  const rec = new MediaRecorder(streamRef.current, { mimeType, videoBitsPerSecond: 2_500_000 });
  rec.ondataavailable = (e) => { if (e.data?.size) chunksRef.current.push(e.data); };
  rec.onstop = () => {
    clearInterval(tickRef.current);
    const duration = Date.now() - startedAtRef.current;
    const blob = new Blob(chunksRef.current, { type: rec.mimeType.split(';')[0] });
    setRecording(false); setElapsed(0);
    if (duration < MIN_RECORD_MS) { /* too short: discard */ setError('Hold a little longer to record a video.'); return; }
    const ext = rec.mimeType.includes('mp4') ? 'mp4' : 'webm';
    addShot(new File([blob], `clip-${stamp()}.${ext}`, { type: blob.type }), 'video', duration);
  };
  recorderRef.current = rec;
  startedAtRef.current = Date.now();
  rec.start(100);
  setRecording(true); setElapsed(0);
  tickRef.current = setInterval(() => {
    const ms = Date.now() - startedAtRef.current;
    setElapsed(ms);
    if (ms >= MAX_VIDEO_SECONDS * 1000) stopRecording();
  }, 100);
}, [recording, ...]);
